import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as I}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"软件流水","description":"","frontmatter":{"title":"软件流水","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/software-pipelining.md","filePath":"cs/software-pipelining.md","lastUpdated":1789023840000}'),c={name:"cs/software-pipelining.md"};function h(m,a,u,_,f,E){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="软件流水" tabindex="-1">软件流水 <a class="header-anchor" href="#软件流水" aria-label="Permalink to &quot;软件流水&quot;">​</a></h1><div class="epigraph"><p>模调度让连续迭代重叠：核（kernel）每 II 拍启动一圈，序言与收尾补满流水。目标是吞吐，不是单圈最短。</p><footer>—— 据 Rau and Glaeser；Lam, Software Pipelining, 1988；Rau, Iterative Modulo Scheduling 整理</footer></div><p>上一课<a href="/cs/list-scheduling">表调度</a>优化单块。循环要<strong>跨迭代重叠</strong>。缺口是软件流水 / 模调度：启动间隔 II 受资源与环依赖约束。本课钉 II、kernel、prologue/epilogue，不写 VLIW 模板全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表调度一圈内排完再下一圈，ALU 仍闲。流水：迭代 \\(i\\) 的 load 与 \\(i+1\\) 的算重叠。II 下界：\\(\\max(\\mathrm{ResMII}, \\mathrm{RecMII})\\)。缺口是<strong>选 II 并放置</strong>，不是块内就绪表。</p><p>若寄存器寿命跨过 II 太长，要旋转或放弃。展开可减 RecMII。</p><h3 id="软件流水不是硬件流水线重讲" tabindex="-1">软件流水不是硬件流水线重讲 <a class="header-anchor" href="#软件流水不是硬件流水线重讲" aria-label="Permalink to &quot;软件流水不是硬件流水线重讲&quot;">​</a></h3><p>组成课五级是 CPU；本课编译器改指令序与核循环。对象不同。</p><p><span class="marginnote">Lam 1988。Rau IMS。Itanium/VLIW 是历史主场；超标量上收益看循环。本课不把 GPU 的软件流水当必须。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算 MII。从 MII 起试调度核。失败则 II++。生成序言（填满）、核、收尾。处理模变量（同一物理寄存器的轮转）。</p>',11)),(e(),n(I,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%BE%AA%E7%8E%AF%E4%BD%93%22%5D%20--%3E%20MII%5B%22Res%2FRec%20MII%22%5D%0A%20%20MII%20--%3E%20KER%5B%22%E6%A8%A1%E8%B0%83%E5%BA%A6%E6%A0%B8%22%5D%0A%20%20KER%20--%3E%20PE%5B%22%E5%BA%8F%E8%A8%80%20%2F%20%E6%94%B6%E5%B0%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与向量化：可先向量化再流水，或放弃其一。别名环依赖会抬 RecMII。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代码体积：序言收尾胀。调试困难。异常：核中间出错，状态难映射源迭代——限制投机。不要对含调用的循环强流水除非内联完。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 SMS 算法变体。后课默认：无环或弱环的内层可模调度。下一课关键路径：给表调度/流水当优先级的路径长度。</p><p>也不把软件流水当 OS 管道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>软件流水：迭代重叠，II 受资源与环约束。</li><li>核 + 序言/收尾；寄存器轮转是实现细节。</li><li>与表调度分层：块内 vs 跨圈。</li><li>出处：Lam, 1988；Rau 模调度；对照 Hennessy–Gross。</li></ul>',8))])}const P=o(c,[["render",h]]);export{g as __pageData,P as default};
